ROOT = "/private/tmp/agent-runs/default/tmpwrxvwanj/pete/projects/towtank-drag"

def read_csv(path):
    with open(path, newline="") as f:
        return list(csv.DictReader(f))

def dynamic_viscosity(T):
    T_K = T + 273.15
    return 2.414e-5 * 10 ** (247.8 / (T_K - 140.0))

def density(T):
    return 1000.0 * (1 - (T + 288.9414) / (508929.2 * (T + 68.12963)) * (T - 3.9863) ** 2)

def viscosity(T):
    return dynamic_viscosity(T) / density(T)

log = read_csv(os.path.join(ROOT, "data/run_log.csv"))
print("nu(13.7)=%.6g nu(17.6)=%.6g nu(20)=%.6g ratio=%.4f" % (viscosity(13.7), viscosity(17.6), viscosity(20), viscosity(13.7)/viscosity(20)))
print("density 13.7, 20:", density(13.7), density(20))

forces = {}
for fn in ["processed/forces.csv", "processed/forces_b3.csv"]:
    for r in read_csv(os.path.join(ROOT, fn)):
        forces[int(r["run"])] = (float(r["F_mean"]), float(r["F_std"]))

# calibration sensitivities
def cal_sens(path):
    rows = read_csv(os.path.join(ROOT, path))
    xs = [float(r["mass_g"]) / 1000.0 * 9.81 for r in rows]
    ys = [float(r["voltage_V"]) for r in rows]
    xm, ym = statistics.mean(xs), statistics.mean(ys)
    return sum((x-xm)*(y-ym) for x, y in zip(xs, ys)) / sum((x-xm)**2 for x in xs)

s2025 = cal_sens("data/calibration/loadcell_2025-09.csv")
s2026 = cal_sens("data/calibration/loadcell_2026-03.csv")
print("sensitivities", s2025, s2026)

# Re, Cd, drift
rows = []
for r in log:
    run = int(r["run_id"]); T = float(r["water_temp_c"]); U = float(r["speed_m_s"]); D = float(r["diameter_mm"])/1000
    nu = viscosity(T); rho = density(T)
    Re = U*D/nu
    F, Fsd = forces[run]
    Cd = F / (0.5*rho*U*U*D*0.60)
    rows.append((run, T, U, D, Re, F, Cd))

# drift from raw
def raw(date, run):
    path = os.path.join(ROOT, "data/raw", date, "run_%03d.csv" % run)
    if date == "2026-03-12":
        with open(path, newline="") as f:
            rr = list(csv.DictReader(f, delimiter=";"))
        return [float(x["t"]) for x in rr], [float(x["V"]) for x in rr]
    with open(path, newline="") as f:
        rr = list(csv.DictReader((line for line in f if not line.startswith("#"))))
    return [float(x["time_s"]) for x in rr], [float(x["loadcell_V"]) for x in rr]

drifts = {}
for r in log:
    run = int(r["run_id"]); t, v = raw(r["date"], run)
    pre = statistics.mean(y for x, y in zip(t, v) if x < 1.0)
    post = statistics.mean(y for x, y in zip(t, v) if x > 10.5)
    drifts[run] = (post-pre)*1000.0

print("max |drift| excluding run 17: %.6f mV" % max(abs(x) for k, x in drifts.items() if k != 17))
print("run17 drift %.3f mV -> 2025 %.4f N, 2026 %.4f N" % (drifts[17], drifts[17]/1000/s2025, drifts[17]/1000/s2026))
print("run17 F=%.4f Cd=%.4f driftfrac=%.4f" % (forces[17][0], [x[6] for x in rows if x[0]==17][0], (drifts[17]/1000/s2025)/forces[17][0]))

# linear interpolation correction at t=5.5 s (centre of window) and average over window
run17 = [x for x in rows if x[0]==17][0]
F17 = forces[17][0]
for frac, label in [(5.5/12, "centre t=5.5"), (0.4583, "mean t over 3-8 ~5.5/12")]:
    Fcorr = F17 - frac*(drifts[17]/1000/s2025)
    print("%s: Fcorr=%.4f Cd=%.4f" % (label, Fcorr, run17[6]*Fcorr/F17))

# Overall stats, slopes, anova
valid = [x for x in rows if x[0] != 17]
Cs = [x[6] for x in valid]
print("n=%d Cd mean=%.6f sd=%.6f min=%.6f max=%.6f" % (len(Cs), statistics.mean(Cs), statistics.stdev(Cs), min(Cs), max(Cs)))
for D in [0.0254, 0.0381, 0.0508]:
    g = [x for x in valid if abs(x[3]-D)<1e-9]
    cc = [x[6] for x in g]
    print("D=%.4f n=%d Cd %.4f sd %.4f range %.4f-%.4f Re %.0f-%.0f" % (D, len(g), statistics.mean(cc), statistics.stdev(cc), min(cc), max(cc), min(x[4] for x in g), max(x[4] for x in g)))

# slope of Cd vs log10 Re overall and by cylinder
def slope(pts):
    xs=[math.log10(x[4]) for x in pts]; ys=[x[6] for x in pts]
    xm=statistics.mean(xs); ym=statistics.mean(ys)
    return sum((x-xm)*(y-ym) for x,y in zip(xs,ys))/sum((x-xm)**2 for x in xs)
print("slope all %.4f" % slope(valid))
for D in [0.0254, 0.0381, 0.0508]:
    print("slope D=%.4f %.4f" % (D, slope([x for x in valid if abs(x[3]-D)<1e-9])))
